  "BEGINNER_TERMS": [
    {
      "term": "prompt",
      "simple_definition": "Une consigne donnée à une IA pour lui expliquer ce que tu veux obtenir."
    },
    {
      "term": "contexte",
      "simple_definition": "Les informations qui aident l’IA à comprendre la situation."
    },
    {
      "term": "contrainte",
      "simple_definition": "Une règle à respecter, par exemple le ton, la longueur ou le format."
    },
    {
      "term": "itération",
      "simple_definition": "Le fait d’améliorer petit à petit une réponse ou un prompt."
    },
    {
      "term": "modèle",
      "simple_definition": "Le moteur IA utilisé, par exemple ChatGPT, Claude ou Gemini."
    },
    {
      "term": "source",
      "simple_definition": "L’endroit d’où vient une information."
    },
    {
      "term": "format",
      "simple_definition": "La forme attendue de la réponse : tableau, liste, email, plan, script, etc."
    },
    {
      "term": "workflow",
      "simple_definition": "Une suite d’étapes pour obtenir un résultat."
    },
    {
      "term": "agent IA",
      "simple_definition": "Une IA qui peut réaliser plusieurs actions ou étapes avec des outils."
    },
    {
      "term": "donnée sensible",
      "simple_definition": "Une information personnelle, confidentielle ou professionnelle à protéger."
    }
  ],
